sql_query:
SELECT "Name of ICI"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung';

SELECT "Control regimen"
FROM clinical_trials
WHERE "Cancer type" = 'NSCLC' AND "Control arm" = 'Chemo';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Type of combination" = 'ICI+MEKi';

SELECT "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Priamry Multiple, composite, or co-primary endpoints?" = 'Yes';

SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Breast' AND "Is any other biomarker used for inclusion" = 'Yes';

SELECT "Type of therapy"
FROM clinical_trials
WHERE "Cancer type" = 'Prostate';

SELECT "Number of arms"
FROM clinical_trials
WHERE "Cancer type" = 'Mesothelioma';

SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Urothelial' AND "Control arm" = 'Placebo';
